// AI Agent Tool: search_code
const pattern = $input.item.json.pattern;
const fileTypes = $input.item.json.fileTypes || [];

// Get repo context from input
const owner = $input.item.json.owner;
const repo = $input.item.json.repo;

if (!owner || !repo) {
  return {
    json: {
      success: false,
      error: 'Missing repository information. Owner: ' + owner + ', Repo: ' + repo,
      matches: []
    }
  };
}

if (!pattern) {
  return {
    json: {
      success: false,
      error: 'Missing search pattern',
      matches: []
    }
  };
}

// Build file extension filter
let fileExtension = '';
if (fileTypes && fileTypes.length > 0) {
  fileExtension = fileTypes.map(t => `+extension:${t}`).join('');
}

// Build GitHub search query
const query = `${pattern}+repo:${owner}/${repo}${fileExtension}`;

try {
  // Call GitHub API
  const response = await fetch(`https://api.github.com/search/code?q=${encodeURIComponent(query)}&per_page=100`, {
    headers: {
      'Authorization': `Bearer ${$env.GITHUB_TOKEN}`,
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28'
    }
  });

  if (!response.ok) {
    throw new Error(`GitHub API returned ${response.status}: ${response.statusText}`);
  }

  const data = await response.json();

  // Format results
  if (!data || !data.items || data.items.length === 0) {
    return {
      json: {
        success: true,
        matches: [],
        total: 0,
        message: `No matches found for pattern: ${pattern}`,
        files: []
      }
    };
  }

  const matches = data.items.map(item => ({
    path: item.path,
    repository: item.repository?.full_name || `${owner}/${repo}`,
    url: item.html_url,
    score: item.score || 0
  }));

  return {
    json: {
      success: true,
      matches: matches,
      total: data.total_count || matches.length,
      message: `Found ${matches.length} matches for '${pattern}'${fileTypes.length > 0 ? ' in ' + fileTypes.join(', ') + ' files' : ''}`,
      files: matches.map(m => m.path)
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: 'GitHub API error: ' + error.message,
      matches: [],
      pattern: pattern,
      query: query
    }
  };
}
